extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var theme_res := load("res://game_theme.tres") as Theme
	if not check("theme_valid", theme_res != null, "Il file game_theme.tres deve essere una risorsa Theme valida"):
		return

	check("default_font_size", theme_res.default_font_size == 18, "La proprietà default_font_size del tema deve essere impostata a 18")

	var states: Array[String] = ["normal", "hover", "pressed", "disabled"]
	for state_name in states:
		var style_box = theme_res.get_stylebox(state_name, "Button") as StyleBoxFlat
		if not check("has_" + state_name, style_box != null, "Il tema deve contenere uno StyleBoxFlat per lo stato '" + state_name + "' di Button"):
			return
		check("radius_" + state_name, style_box.corner_radius_top_left == 6 and style_box.corner_radius_bottom_right == 6, "Lo stile '" + state_name + "' deve avere il raggio degli angoli impostato a 6 pixel")

	var basket_root := await instantiate_scene("res://basket.tscn")
	if not check("basket_loaded", basket_root != null, "La scena basket.tscn deve potersi istanziare"):
		return
	var restart_btn := find_by_name(basket_root, "RestartButton") as Button
	if not check("btn_found", restart_btn != null, "La scena basket.tscn deve contenere il nodo RestartButton"):
		return
	check("btn_has_theme", restart_btn.theme == theme_res, "RestartButton deve avere game_theme.tres associato alla proprietà Theme")

extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var theme_res := load("res://game_theme.tres") as Theme
	if not check("theme_exists", theme_res != null, "Il file game_theme.tres deve esistere"):
		return

	var menu_root := await instantiate_scene("res://mode_menu.tscn")
	if not check("menu_loaded", menu_root != null, "La scena mode_menu.tscn deve potersi istanziare"):
		return
	var menu_control := menu_root as Control
	check("menu_theme", menu_control.theme == theme_res, "La radice ModeMenu deve avere game_theme.tres assegnato come Theme")

	var header_label := find_by_name(menu_root, "HeaderLabel") as Label
	if check("header_exists", header_label != null, "HeaderLabel deve esistere in mode_menu.tscn"):
		check("header_override", header_label.get_theme_font_size("font_size") == 28, "HeaderLabel deve avere una dimensione del font di 28 pixel")

	var classic_btn := find_by_name(menu_root, "ClassicButton") as Button
	if check("btn_exists", classic_btn != null, "ClassicButton deve esistere nel menu"):
		check("btn_no_local_theme", classic_btn.theme == null, "I singoli pulsanti non devono avere un tema locale ma ereditarlo")
		var inherited_box = classic_btn.get_theme_stylebox("normal") as StyleBoxFlat
		check("btn_inherited_style", inherited_box != null and inherited_box.corner_radius_top_left == 6, "I pulsanti devono ereditare lo stile del tema generale")

	var hud_root := await instantiate_scene("res://hud.tscn")
	if not check("hud_loaded", hud_root != null, "La scena hud.tscn deve potersi istanziare"):
		return
	var hud_control := hud_root as Control
	check("hud_theme", hud_control.theme == theme_res, "La radice HUD deve avere game_theme.tres assegnato come Theme")

	var message_label := find_by_name(hud_root, "MessageLabel") as Label
	if check("msg_label_exists", message_label != null, "MessageLabel deve esistere in hud.tscn"):
		check("msg_override", message_label.get_theme_font_size("font_size") == 24, "MessageLabel deve avere una dimensione del font di 24 pixel")

extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var theme_res := load("res://game_theme.tres") as Theme
	if not check("theme_ok", theme_res != null, "Il tema game_theme.tres deve esistere"):
		return

	var panel_box = theme_res.get_stylebox("panel", "Panel") as StyleBoxFlat
	if not check("panel_box", panel_box != null, "Il tema deve contenere uno StyleBoxFlat per lo stile 'panel' di Panel"):
		return
	check("panel_border", panel_box.border_width_left == 2 and panel_box.border_width_top == 2, "Lo stile Panel deve avere un bordo di 2 pixel")
	check("panel_radius", panel_box.corner_radius_top_left == 8, "Lo stile Panel deve avere angoli arrotondati a 8 pixel")

	var hud_node := await instantiate_scene("res://hud.tscn")
	if not check("hud_instantiated", hud_node != null, "hud.tscn deve potersi istanziare senza errori"):
		return

	var message_panel := find_by_name(hud_node, "MessagePanel") as Panel
	if not check("panel_exists", message_panel != null, "MessagePanel deve esistere"):
		return
	check("panel_no_local_theme", message_panel.theme == null, "MessagePanel non deve avere un tema locale ma ereditare da HUD")

	var hud_script = hud_node
	if check("hud_has_method", has_function(hud_script, "show_message"), "hud.gd deve contenere il metodo show_message"):
		call_if_exists(hud_script, "show_message", ["TestCornice"])
		var msg_label := find_by_name(hud_node, "MessageLabel") as Label
		if check("label_exists", msg_label != null, "MessageLabel deve esistere dentro MessagePanel"):
			check("label_updated", msg_label.text == "TestCornice", "Il metodo show_message() deve aggiornare correttamente il testo di MessageLabel")

